// Parrot content script. Injected only on origins the user enabled from the popup
// (registered at runtime via chrome.scripting.registerContentScripts). No network calls here:
// everything goes through the service worker. No DOM changes yet.

import { send } from "../messages";
// TODO(karthik): wordindex.json (English form -> lemmas) is generated by scripts/build-wordlist.
import wordindex from "../wordindex.json";

// TODO(naren): pipeline from docs/architecture.md §6:
// TODO(naren): 1. TreeWalker over visible text nodes, skipping a, button, input, textarea, select,
//                 code, pre, script, style, [contenteditable] and anything inside form.
// TODO(naren): 1b. MutationObserver (debounced) for content added after load.
// TODO(naren): 2. Tokenize and look up English forms in wordindex.
// TODO(naren): 3. Get word states from the service worker (cached /api/candidates) and score
//                 (specs §5.2, 70% review / 30% new).
// TODO(naren): 4. Spacing: max one swap per sentence, never adjacent, per-page cap 25.
// TODO(naren): 5. Send chosen sentences to the service worker for one /api/translate batch;
//                 apply swaps only after it returns.
